/**
 * PWA Cache Management Utility
 *
 * Handles Service Worker cache versioning, detection, and clearing
 * to prevent blank screen issues when caches become stale.
 *
 * Features:
 * - App version tracking
 * - Automatic cache clearing on version mismatch
 * - Manual cache clearing
 * - Service Worker unregistration
 * - Diagnostic information
 */

import logger from './logger';
import { CONSTANTS } from 'src/constants';

interface CacheDiagnostics {
  hasServiceWorker: boolean;
  registrations: number;
  cacheNames: string[];
  appVersion: string;
  storedVersion: string;
  versionMismatch: boolean;
}

class PWACacheManager {
  private readonly VERSION_KEY = CONSTANTS.app_version;
  private readonly CACHE_PREFIX = 'fc-ocr-vue-precache';

  /**
   * Get current app build version
   */
  getCurrentVersion(): string {
    // Use build-time injected version or fallback
    return (import.meta.env.VITE_APP_VERSION || '1.0.0').trim();
  }

  /**
   * Get stored version from localStorage
   */
  getStoredVersion(): string {
    try {
      return localStorage.getItem(this.VERSION_KEY) || '';
    } catch (error) {
      logger.warn('[PWA Cache] Failed to read stored version:', error);
      return '';
    }
  }

  /**
   * Store current version in localStorage
   */
  storeCurrentVersion(): void {
    try {
      const version = this.getCurrentVersion();
      localStorage.setItem(this.VERSION_KEY, version);
      logger.debug('[PWA Cache] Version stored:', version);
    } catch (error) {
      logger.warn('[PWA Cache] Failed to store version:', error);
    }
  }

  /**
   * Check if version has changed
   */
  hasVersionChanged(): boolean {
    const currentVersion = this.getCurrentVersion();
    const storedVersion = this.getStoredVersion();
    const changed = currentVersion !== storedVersion && !!storedVersion;

    if (changed) {
      logger.warn('[PWA Cache] Version mismatch detected:', {
        current: currentVersion,
        stored: storedVersion,
      });
    }

    return changed;
  }

  /**
   * Clear all Service Worker caches
   */
  async clearAllCaches(): Promise<void> {
    if (!('caches' in window)) {
      logger.warn('[PWA Cache] Caches API not available');
      return;
    }

    try {
      const cacheNames = await caches.keys();
      logger.info('[PWA Cache] Found caches to clear:', cacheNames);

      const deletePromises = cacheNames.map((name) => {
        logger.debug('[PWA Cache] Deleting cache:', name);
        return caches.delete(name);
      });

      const results = await Promise.all(deletePromises);
      const deleted = results.filter((r) => r).length;

      logger.info(`[PWA Cache] Cleared ${deleted}/${cacheNames.length} caches`);
    } catch (error) {
      logger.error('[PWA Cache] Error clearing caches:', error);
    }
  }

  /**
   * Unregister all Service Workers
   */
  async unregisterServiceWorkers(): Promise<void> {
    if (!('serviceWorker' in navigator)) {
      logger.warn('[PWA Cache] Service Worker API not available');
      return;
    }

    try {
      const registrations = await navigator.serviceWorker.getRegistrations();
      logger.info('[PWA Cache] Found Service Workers to unregister:', registrations.length);

      const unregisterPromises = registrations.map((reg) => {
        logger.debug('[PWA Cache] Unregistering Service Worker:', reg.scope);
        return reg.unregister();
      });

      const results = await Promise.all(unregisterPromises);
      const unregistered = results.filter((r) => r).length;

      logger.info(
        `[PWA Cache] Unregistered ${unregistered}/${registrations.length} Service Workers`
      );
    } catch (error) {
      logger.error('[PWA Cache] Error unregistering Service Workers:', error);
    }
  }

  /**
   * Perform complete cache cleanup
   */
  async performFullCleanup(): Promise<void> {
    logger.warn('[PWA Cache] Performing full cache cleanup...');

    try {
      await this.clearAllCaches();
      await this.unregisterServiceWorkers();
      this.storeCurrentVersion();
      logger.info('[PWA Cache] Full cleanup completed');
    } catch (error) {
      logger.error('[PWA Cache] Full cleanup failed:', error);
    }
  }

  /**
   * Get diagnostic information
   */
  async getDiagnostics(): Promise<CacheDiagnostics> {
    const hasServiceWorker = 'serviceWorker' in navigator;
    let registrations = 0;
    let cacheNames: string[] = [];

    try {
      if (hasServiceWorker) {
        const regs = await navigator.serviceWorker.getRegistrations();
        registrations = regs.length;
      }

      if ('caches' in window) {
        cacheNames = await caches.keys();
      }
    } catch (error) {
      logger.warn('[PWA Cache] Error getting diagnostics:', error);
    }

    const currentVersion = this.getCurrentVersion();
    const storedVersion = this.getStoredVersion();

    return {
      hasServiceWorker,
      registrations,
      cacheNames,
      appVersion: currentVersion,
      storedVersion,
      versionMismatch: currentVersion !== storedVersion && !!storedVersion,
    };
  }

  /**
   * Check and auto-recover from cache issues on boot
   */
  async autoRecoverIfNeeded(): Promise<boolean> {
    const versionChanged = this.hasVersionChanged();

    if (versionChanged) {
      logger.warn('[PWA Cache] Version change detected - performing cache cleanup');
      await this.performFullCleanup();
      return true;
    }

    // Store current version for future comparisons
    this.storeCurrentVersion();
    return false;
  }
}

// Export singleton instance
export const pwaCacheManager = new PWACacheManager();
export default pwaCacheManager;
